  + Rating : int
}

class HotelChain {
  + Name : string
}

class City {
  + Name : string
}

class RoomType {
  + Type : string
}

class Booking {
  + BookingIdentifier : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : RoomType
  + MaxCostPerNight : float
  + Status : string
  + CancellationDeadline : date
}

class SpecialOffer {
  + Price : float
  + OfferDetails : string
}

class CreditCardInfo {
  + CardNumber : string
}

class PaymentMethod {
  + Method : string
}

class SearchCriteria {
  + City : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : string
  + MinRating : int
  + MaxCostPerNight : float
  + Preferences : string[]
}

Traveller "1" -- "*" Booking : makes
Traveller "1" -- "0..1" CreditCardInfo : provides
Traveller "1" -- "*" SpecialOffer : receives
Hotel "0..*" -- "1" City : located in
Hotel "0..*" -- "0..1" HotelChain : run by
Hotel "1" -- "*" Booking : confirms
Hotel "1" -- "*" RoomType : offers
Booking "1" -- "1" PaymentMethod : uses
Booking "1" -- "0..*" SpecialOffer : can switch to

@enduml

